<?php
declare(strict_types=1);
require __DIR__.'/../private/bootstrap.php';require __DIR__.'/../private/validate.php';require __DIR__.'/../private/storage.php';require __DIR__.'/../private/operations.php';require __DIR__.'/../private/calendar-plan.php';require __DIR__.'/../private/billing.php';
try{headers_private();$u=require_user();$current=read_state();
 if($_SERVER['REQUEST_METHOD']==='POST'){
