 page('Revisar calendario futuro','<p>Servicios configurados: '.count($plan['services']).'. Inicio: noviembre 2026. Se conservan '.count($next['clients']).' fichas, '.count($next['charges']).' cobros y '.count($next['payments']).' pagos. No se añade ningún movimiento hoy. Los valores desconocidos mantienen vencimiento nulo.</p><pre style="white-space:pre-wrap;overflow-wrap:anywhere">'.e(json_encode($plan['services'],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)).'</pre><form method="post"><input type="hidden" name="csrf" value="'.e(csrf()).'"><button name="apply" value="1">Activar calendario aprobado</button></form>');exit;}
 ensure(($_POST['apply']??'')==='1'&&isset($_SESSION['calendar_plan']),'Plan no preparado.');$p=$_SESSION['calendar_plan'];$p['action']='Calendario futuro confirmado; sin reconstrucción histórica';$result=save_state($p,$u);unset($_SESSION['calendar_plan']);page('Calendario activado','<p>Guardado en revisión '.(int)$result['revision'].'. No se crearon cobros ni pagos durante la activación.</p><p><a href="./">Volver a la herramienta</a></p>');exit;
 }
 page('Calendario futuro por servicio','<p>Esta pantalla importa únicamente reglas futuras y alias confirmados sobre IDs existentes. No sustituye fichas, cobros ni pagos. Antes de activar muestra un resumen para revisión.</p><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="'.e(csrf()).'"><label>Plan de calendario validado<input type="file" name="plan" accept=".json" required></label><button>Revisar plan</button></form>');
}catch(Throwable $e){http_response_code(400);page('Calendario no modificado','<p>'.e($e instanceof DomainException?$e->getMessage():'No se pudo preparar o guardar el calendario.').'</p>');}
